source("00_helpers.R")
set.seed(3); ids <- sample(s30$nodes$source_id, 8000); n <- s30$nodes[s30$nodes$source_id %in% ids, ]; r <- s30$refs[s30$refs$source_id %in% ids, ]
nets <- run("build with empty windows (all years, 10y)", build_dynamic_networks(n, r, "source_id", "target_id", method = "angle", time_variable = "year", time_window = 10, window_step = 5, edges_threshold = 2))
cat(" ", paste(names(nets), sapply(nets, igraph::vcount), collapse = " "), "\n")
nets <- run("add_clusters with empty windows", add_clusters(nets, clustering_method = "leiden", objective_function = "modularity", seed = 1))
m <- run("merge with empty windows", merge_dynamic_clusters(nets, "cluster_leiden", "source_id", method = "jaccard", threshold_similarity = 0.3, similarity_type = "partial"))
x <- run("name tf-idf with empty windows", name_clusters(m, method = "tf-idf", name_dynamic_clusters = TRUE, cluster_id = "dynamic_cluster_leiden", text_columns = "title", clean_word_method = "stemming"))
x <- run("roles with empty windows", add_node_roles(m, cluster_id = "cluster_leiden"))
x <- run("colour with empty windows", color_networks(m, column_to_color = "dynamic_cluster_leiden", verbose = FALSE))
x <- run("layout with empty windows", { set.seed(1); layout_networks(x, node_id = "source_id", layout = "fr", compute_dynamic_coordinates = TRUE) })
p <- run("plot_networks with empty windows", plot_networks(x, cluster_label_column = "dynamic_cluster_leiden", node_size_column = NULL))
a <- run("alluvial with empty windows", networks_to_alluv(x, "dynamic_cluster_leiden", "source_id"))
p <- run("plot_alluvial with empty windows", print(plot_alluvial(a, "dynamic_cluster_leiden", "source_id", minimize_crossing = TRUE)))
# single graph inputs to list functions, etc.
g <- build_network(jme$nodes[jme$nodes$year < 1990,], jme$refs, "source_id", "target_id", method = "angle", verbose = FALSE)
x <- run("merge on a single graph", merge_dynamic_clusters(g, "cluster_leiden", "source_id", method = "majority", threshold_similarity = .6, similarity_type = "partial"))
x <- run("add_clusters no algorithm", add_clusters(g))
x <- run("add_clusters leiden no objective", add_clusters(g, clustering_method = "leiden"))
x <- run("add_clusters seed reproducible", { a <- add_clusters(g, clustering_method = "leiden", objective_function = "modularity", seed = 3, verbose = FALSE); b <- add_clusters(g, clustering_method = "leiden", objective_function = "modularity", seed = 3, verbose = FALSE); cat("  same:", identical(tidygraph::as_tibble(a)$cluster_leiden, tidygraph::as_tibble(b)$cluster_leiden), "\n") })
gc1 <- add_clusters(g, clustering_method = "leiden", objective_function = "modularity", seed = 3, verbose = FALSE)
x <- run("add_clusters twice", add_clusters(gc1, clustering_method = "leiden", objective_function = "modularity", seed = 3))
x <- run("name_clusters missing text column", name_clusters(gc1, method = "tf-idf", cluster_id = "cluster_leiden", text_columns = "abstract"))
x <- run("name_clusters given_column no order_by", name_clusters(gc1, method = "given_column", cluster_id = "cluster_leiden", label_columns = "title"))
x <- run("name_clusters tidygraph no function", name_clusters(gc1, method = "tidygraph_functions", cluster_id = "cluster_leiden", label_columns = "title"))
x <- run("color_networks no column", color_networks(gc1, column_to_color = "cluster"))
x <- run("layout no node_id", layout_networks(gc1, layout = "fr"))
x <- run("layout unknown", layout_networks(gc1, node_id = "source_id", layout = "nope"))
x <- run("plot_networks without layout", plot_networks(gc1, cluster_label_column = "cluster_leiden", node_size_column = NULL))
x <- run("plot_networks without size col (default node_size)", { set.seed(1); y <- layout_networks(gc1, "source_id", "fr"); print(plot_networks(y, cluster_label_column = "cluster_leiden")) })
x <- run("add_node_roles on single graph", add_node_roles(gc1, cluster_id = "cluster_leiden"))
x <- run("filter_components 3", filter_components(gc1, nb_components = 3))
x <- run("extract_tfidf on a data frame", extract_tfidf(jme$nodes, text_columns = "title", grouping_columns = "year", clean_word_method = "none"))
if (!inherits(x, "err")) print(head(x, 3))
